package org.diy.liferecorder;
import android.content.*;import org.json.*;
/** Durable hash-bound removal commands. A pending command is never presented as a completed deletion. */
final class WatchArchive {
 static void schema(android.database.sqlite.SQLiteDatabase db){db.execSQL("CREATE TABLE IF NOT EXISTS watch_files(device TEXT NOT NULL,name TEXT NOT NULL,sha TEXT NOT NULL,bytes INTEGER NOT NULL,created INTEGER NOT NULL,present INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(device,name))");db.execSQL("CREATE TABLE IF NOT EXISTS watch_commands(id TEXT PRIMARY KEY,device TEXT NOT NULL,name TEXT NOT NULL,sha TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL)");}
 static String device(Context c){return c.getSharedPreferences("device-sync",0).getString("device","");}
 static void request(RecordStore db,String source)throws Exception{JSONObject a=db.audio(source),meta=new JSONObject(a.optString("metadata","{}"));String name=meta.optString("audio_file"),device=meta.optString("watch_device",device(db.context));if(name.isEmpty()||device.isEmpty())throw new java.io.IOException("该录音没有已配对手表来源");requestFile(db,device,name,a.getString("sha"));}
 static void requestFile(RecordStore db,String device,String name,String sha)throws Exception{if(!name.matches("[A-Za-z0-9_+.:-]{1,220}\\.m4a")||!sha.matches("[a-f0-9]{64}"))throw new java.io.IOException("手表文件身份无效");if(db.rows("SELECT id FROM watch_commands WHERE device=? AND name=? AND sha=? AND status='pending'",device,name,sha).length()>0)return;ContentValues v=new ContentValues();v.put("id",java.util.UUID.randomUUID().toString());v.put("device",device);v.put("name",name);v.put("sha",sha);v.put("status","pending");v.put("created",System.currentTimeMillis());db.getWritableDatabase().insertOrThrow("watch_commands",null,v);}
 static JSONObject policy(RecordStore db,String device)throws Exception{JSONObject result=new JSONObject().put("version",1).put("retention_days",7).put("commands",db.rows("SELECT id,name,sha FROM watch_commands WHERE device=? AND status='pending' ORDER BY created LIMIT 200",device));JSONArray processed=new JSONArray();JSONArray rows=db.rows("SELECT sha,metadata FROM audio WHERE speech_json<>'' OR analysis<>'' ORDER BY created DESC LIMIT 10000");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);String name=new JSONObject(row.optString("metadata","{}")).optString("audio_file");if(!name.isEmpty())processed.put(new JSONObject().put("name",name).put("sha",row.getString("sha")));}return result.put("processed",processed);}
 static void accept(RecordStore db,String device,JSONObject report)throws Exception{JSONArray inventory=report.getJSONArray("files"),acks=report.getJSONArray("acks");if(inventory.length()>10000||acks.length()>200)throw new java.io.IOException("手表清单过大");android.database.sqlite.SQLiteDatabase sql=db.getWritableDatabase();sql.beginTransaction();try{for(int i=0;i<acks.length();i++){JSONObject ack=acks.getJSONObject(i);String status=ack.getString("status");if(!status.equals("deleted")&&!status.equals("absent")&&!status.equals("mismatch")&&!status.equals("failed"))throw new java.io.IOException("删除回执无效");sql.execSQL("UPDATE watch_commands SET status=? WHERE id=? AND device=? AND name=? AND sha=? AND status='pending'",new Object[]{status,ack.getString("id"),device,ack.getString("name"),ack.getString("sha")});}sql.execSQL("UPDATE watch_files SET present=0 WHERE device=?",new Object[]{device});for(int i=0;i<inventory.length();i++){JSONObject f=inventory.getJSONObject(i);if(!f.getString("name").matches("[A-Za-z0-9_+.:-]{1,220}\\.m4a")||!f.getString("sha").matches("[a-f0-9]{64}"))throw new java.io.IOException("清单身份无效");ContentValues v=new ContentValues();v.put("device",device);v.put("name",f.getString("name"));v.put("sha",f.getString("sha"));v.put("bytes",f.getLong("bytes"));v.put("created",f.getLong("created"));v.put("present",1);sql.insertWithOnConflict("watch_files",null,v,android.database.sqlite.SQLiteDatabase.CONFLICT_REPLACE);}sql.setTransactionSuccessful();}finally{sql.endTransaction();}db.context.getSharedPreferences("device-sync",0).edit().putLong("archive_sync_at",System.currentTimeMillis()).apply();}
}
